package org.apache.commons.math.complex;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.apache.commons.math.FieldElement;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.exception.NullArgumentException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.MathUtils;
import org.apache.commons.math3.exception.NullArgumentException;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for the add method of org.apache.commons.math3.complex.Complex.
 */
public class Complex_add_TriageGen2Test {

    @Test
    public void testAdd_PositiveRealAndImaginary() {
        Complex c1 = new Complex(1.0, 2.0);
        Complex c2 = new Complex(3.0, 4.0);
        Complex expected = new Complex(4.0, 6.0);
        Complex result = c1.add(c2);
        Assert.assertEquals("Adding two positive complex numbers failed", expected, result);
    }

    @Test
    public void testAdd_NegativeValues() {
        Complex c1 = new Complex(-1.5, -2.5);
        Complex c2 = new Complex(-3.5, -4.5);
        Complex expected = new Complex(-5.0, -7.0);
        Complex result = c1.add(c2);
        Assert.assertEquals("Adding two negative complex numbers failed", expected, result);
    }

    @Test
    public void testAdd_Zero() {
        Complex c1 = new Complex(5.0, 5.0);
        Complex c2 = new Complex(0.0, 0.0);
        Complex expected = new Complex(5.0, 5.0);
        Complex result = c1.add(c2);
        Assert.assertEquals("Adding zero failed", expected, result);
    }

    @Test
    public void testAdd_MixedSigns() {
        Complex c1 = new Complex(10.0, -5.0);
        Complex c2 = new Complex(-2.0, 3.0);
        Complex expected = new Complex(8.0, -2.0);
        Complex result = c1.add(c2);
        Assert.assertEquals("Adding mixed sign complex numbers failed", expected, result);
    }

    @Test
    public void testAdd_NaN() {
        Complex c1 = new Complex(Double.NaN, 1.0);
        Complex c2 = new Complex(1.0, 1.0);
        Complex result = c1.add(c2);
        Assert.assertTrue("Resulting real part should be NaN", Double.isNaN(result.getReal()));
        Assert.assertEquals(2.0, result.getImaginary(), 1e-10);
    }

    @Test
    public void testAdd_Infinite() {
        Complex c1 = new Complex(Double.POSITIVE_INFINITY, 1.0);
        Complex c2 = new Complex(1.0, 1.0);
        Complex result = c1.add(c2);
        Assert.assertTrue("Resulting real part should be Infinite", Double.isInfinite(result.getReal()));
        Assert.assertEquals(2.0, result.getImaginary(), 1e-10);
    }

    @Test(expected = NullArgumentException.class)
    public void testAdd_NullArgument() {
        Complex c1 = new Complex(1.0, 1.0);
        c1.add(null);
    }
}
